True def transform(grid):
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    pixels4 = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    pixels6 = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if not pixels4 or not pixels6:
        return out
    mean_r6 = sum(r for r, _ in pixels6) / len(pixels6)
    mean_c6 = sum(c for _, c in pixels6) / len(pixels6)
    var_r6 = sum((r - mean_r6) ** 2 for r, _ in pixels6)
    var_c6 = sum((c - mean_c6) ** 2 for _, c in pixels6)
    for r, c in pixels6:
        out[r][c] = 0
    if var_c6 > var_r6:
        top = min(r for r, _ in pixels4)
        bottom = max(r for r, _ in pixels4)
        if 2 * bottom + 1 - top < h:
            reflected = lambda r, c: (2 * bottom + 1 - r, c)
        else:
            reflected = lambda r, c: (2 * top - 1 - r, c)
    else:
        left = min(c for _, c in pixels4)
        right = max(c for _, c in pixels4)
        if 2 * right + 1 - left < w:
            reflected = lambda r, c: (r, 2 * right + 1 - c)
        else:
            reflected = lambda r, c: (r, 2 * left - 1 - c)
    for r, c in pixels4:
        rr, cc = reflected(r, c)
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
    return out
